mapper.select:
SELECT r.* FROM kb_product r LEFT JOIN kb_product_profile p ON p.product_id=r.id

    AND r.title LIKE CONCAT('%',#{title},'%')
    AND p.subject=#{subject}
    AND COALESCE(p.resource_type,'UNKNOWN')=#{resourceType}
    AND COALESCE(p.catalog_status,'DRAFT')=#{catalogStatus}
    AND p.audience_role=#{audienceRole}
    AND COALESCE(p.provenance_status,'UNKNOWN')=#{provenanceStatus}
    AND r.root_product_id=#{rootProductId}
    AND r.material_id=#{materialId}
    AND NOT EXISTS(SELECT 1 FROM kb_product newer WHERE newer.root_product_id=r.root_product_id AND newer.version_no > r.version_no)

     AND p.published_yearp.prepared_yearNULL >= #{yearFrom}
     AND p.published_yearp.prepared_yearNULL <= #{yearTo}


      AND EXISTS(SELECT 1 FROM kb_product_outline_scope sc JOIN kb_outline o ON o.id=sc.outline_id WHERE sc.product_id=r.id
       AND sc.outline_id=#{outlineId}
       AND o.textbook_version=#{textbookVersion}
       AND o.grade=#{grade}
       AND o.term=#{term}
       AND (sc.scope_kind='WHOLE_BOOK' OR (sc.scope_kind='CHAPTERS' AND EXISTS(SELECT 1 FROM kb_product_outline_scope_node sn WHERE sn.scope_id=sc.id AND (sn.node_id IN #{n}
        OR sn.node_id IN #{n}))))
      )

    AND EXISTS(SELECT 1 FROM kb_product_region rg WHERE rg.product_id=r.id AND rg.region_role=#{regionRole} AND rg.region_code IN #{code})
    AND ((r.render_job_id IS NULL AND EXISTS(SELECT 1 FROM kb_product_question l JOIN kb_question_kp qk ON qk.question_id=l.question_id WHERE l.product_id=r.id AND qk.kp_id=#{kpId})) OR (r.render_job_id IS NOT NULL AND EXISTS(SELECT 1 FROM JSON_TABLE(r.snapshot_json, '$.declaredKpIds[*]' COLUMNS(kp_id BIGINT PATH '$')) frozen WHERE frozen.kp_id=#{kpId})))AND EXISTS(SELECT 1 FROM kb_product_kp dk WHERE dk.product_id=r.id AND dk.kp_id=#{kpId})
 ORDER BY r.id DESC

SELECT version_no + 1 FROM kb_product
WHERE root_product_id=#{rootId}
ORDER BY version_no DESC LIMIT 1 FOR UPDATE
